  x: *u32,

  fn init(allocator: *std.mem.Allocator, value: u32) void {
    self.x = allocator.create(u32);
    self.x.* = value;
  }

  // variables may be re-assigned to `undefined` in destructors
  fn deinit(self: *Foo, alloc: std.mem.Allocator) void {
